    settings_report_empty: 'No active protocols to report on.',
    settings_data_privacy: 'Data & privacy',
    settings_privacy_policy: 'Privacy policy',
    settings_privacy_body: "PRIVACY POLICY\n\nLast updated: April 2026\n\nOutcom operates the DoseTrace mobile application.\n\nDATA WE COLLECT\nWhen you create an account, we collect your email address. You may optionally provide your name, gender, birth month and year, country, wellness goals, activity level, and whether you work with a healthcare provider. Protocol data, dose logs, vial records, and reminders you create are saved on your device and synced — encrypted in transit — to our secure cloud (Supabase, United States), so your data is backed up and available across your devices.\n\nHOW WE USE YOUR DATA\nWe use your data to provide and personalize the DoseTrace service. Profile information (name, gender, age range, country, goals, activity level) may be used in aggregate and anonymized form to improve our service. Apart from the AI extraction described below, we do not share individual user data with third parties. We do not sell your personal data. We do not use your health data for advertising purposes.\n\nAI EXTRACTION (OPTIONAL)\nIf you choose to scan a lab report or vaccine card, the photo or PDF you select is transmitted to Anthropic PBC (the Claude AI service) for one-time text extraction, only after you give explicit permission in the app. Only the selected file is sent. It is used solely to extract the values, is not used to train AI models, and is not retained by Anthropic beyond short-term abuse monitoring. Anthropic protects this data with safeguards equivalent to this policy.\n\nDATA STORAGE\nYour data is stored on your device and synced, encrypted in transit, to Supabase secure cloud servers in the United States, so it is backed up and available across your devices.\nLab reports and vaccine cards you choose to scan are additionally sent once to Anthropic for text extraction, as described above.\n\nYOUR RIGHTS\nYou may delete your account and all associated data at any time from Settings in the app, or by contacting hello@dosetrace.io.\n\nCHILDREN\nDoseTrace is not intended for use by individuals under the age of 18.\n\nCHANGES\nWe may update this policy periodically. Continued use of the app constitutes acceptance of the updated policy.\n\nCONTACT\nhello@dosetrace.io",
    settings_terms: 'Terms of service',
    settings_terms_body: "TERMS OF SERVICE\n\nLast updated: April 2026\n\nBy downloading or using DoseTrace, you agree to these terms.\n\nUSE OF THE APP\nDoseTrace is provided for personal wellness tracking purposes only. You must be 18 or older to use this app. You are responsible for maintaining the confidentiality of your account credentials.\n\nMEDICAL DISCLAIMER\nDoseTrace does not provide medical advice. See our Medical Disclaimer for full details.\n\nPREMIUM SUBSCRIPTION\nPremium features are available via subscription at the price shown in the app at the time of purchase. Subscriptions auto-renew unless cancelled at least 24 hours before the renewal date. Manage subscriptions in your Apple ID settings.\n\nINTELLECTUAL PROPERTY\nAll content, features, and functionality of DoseTrace are owned by Outcom and protected by applicable intellectual property laws.\n\nLIMITATION OF LIABILITY\nOutcom shall not be liable for any indirect, incidental, or consequential damages arising from your use of DoseTrace.\n\nTERMINATION\nWe reserve the right to terminate accounts that violate these terms.\n\nGOVERNING LAW\nThese terms are governed by the laws of the State of Florida, United States.\n\nCONTACT\nhello@dosetrace.io",
    settings_disclaimer: 'Medical disclaimer',
    settings_disclaimer_body: "WELLNESS DISCLAIMER\n\nDoseTrace is a personal wellness tracking tool designed for informational and organizational purposes only.\n\nDoseTrace does not provide medical advice, diagnosis, or treatment recommendations. All content within this app is for general informational purposes only.\n\nNothing in this app should be construed as medical advice or used as a substitute for professional medical advice, diagnosis, or treatment. Always seek the guidance of a qualified healthcare provider before starting, adjusting, or stopping any wellness regimen.\n\nAll features within DoseTrace are passive data recording utilities. They help you log and visualize your own self-reported data. They do not validate, endorse, or recommend any specific protocol, dosage, or outcome. All mathematical calculations are estimates based on user-provided inputs and are not biological predictions.\n\nBy using DoseTrace, you acknowledge that:\n\n- You are using this app at your own risk\n- You take full responsibility for any decisions made based on information recorded in this app\n- DoseTrace and Outcom are not liable for any harm arising from use of this app\n- This app is not intended to diagnose, treat, cure, or prevent any disease or medical condition\n\nIf you are experiencing a medical emergency, call emergency services immediately.",
