    settings_persistent: 'Recordatorios persistentes',
    settings_persistent_sub: 'Repetir recordatorios cada 5 min hasta confirmar',
    settings_report_title: 'Informe de adherencia',
    settings_report_sub: 'Comparte un resumen de 30 días con tu profesional de la salud',
    settings_report_empty: 'No hay protocolos activos para incluir en el informe.',
    settings_data_privacy: 'Datos y privacidad',
    settings_privacy_policy: 'Política de privacidad',
    settings_privacy_body: "POLÍTICA DE PRIVACIDAD\n\nÚltima actualización: abril de 2026\n\nOutcom opera la aplicación móvil DoseTrace.\n\nDATOS QUE RECOPILAMOS\nCuando creas una cuenta, recopilamos tu dirección de correo electrónico. De forma opcional, puedes proporcionar tu nombre, sexo, mes y año de nacimiento, país, objetivos de bienestar, nivel de actividad y si trabajas con un profesional sanitario. Los datos de protocolos, registros de dosis, registros de viales y recordatorios que creas se guardan en tu dispositivo y se sincronizan, cifrados en tránsito, con nuestra nube segura (Supabase, Estados Unidos), de modo que tus datos tienen copia de seguridad y están disponibles en tus dispositivos.\n\nCÓMO USAMOS TUS DATOS\nUsamos tus datos para proporcionar y personalizar el servicio DoseTrace. La información opcional del perfil (nombre, sexo, rango de edad, país, objetivos, nivel de actividad) puede utilizarse de forma agregada y anonimizada para mejorar nuestro servicio. Aparte de la extracción con IA descrita abajo, no compartimos datos individuales de usuarios con terceros. No vendemos tus datos personales. No usamos tus datos de salud con fines publicitarios.\n\nEXTRACCIÓN CON IA (OPCIONAL)\nSi decides escanear un informe de laboratorio o un carné de vacunación, la foto o el PDF que selecciones se transmite a Anthropic PBC (el servicio de IA Claude) para una extracción de texto única, solo después de que des tu permiso explícito en la app. Solo se envía el archivo seleccionado. Se usa únicamente para extraer los valores, no se utiliza para entrenar modelos de IA y Anthropic no lo conserva más allá de la supervisión antiabusos a corto plazo. Anthropic protege estos datos con garantías equivalentes a esta política.\n\nALMACENAMIENTO DE DATOS\nTus datos se almacenan en tu dispositivo y se sincronizan, cifrados en tránsito, con los servidores seguros en la nube de Supabase en los Estados Unidos, de modo que tienen copia de seguridad y están disponibles en tus dispositivos.\nLos informes de laboratorio y carnés de vacunación que decidas escanear se envían además una sola vez a Anthropic para la extracción de texto, como se describe arriba.\n\nTUS DERECHOS\nPuedes eliminar tu cuenta y todos los datos asociados en cualquier momento desde Ajustes en la app, o escribiendo a hello@dosetrace.io.\n\nMENORES\nDoseTrace no está destinada al uso por personas menores de 18 años.\n\nCAMBIOS\nPodemos actualizar esta política periódicamente. El uso continuado de la aplicación constituye la aceptación de la política actualizada.\n\nCONTACTO\nhello@dosetrace.io",
    settings_terms: 'Términos de servicio',
    settings_terms_body: "TÉRMINOS DE SERVICIO\n\nÚltima actualización: abril de 2026\n\nAl descargar o usar DoseTrace, aceptas estos términos.\n\nUSO DE LA APLICACIÓN\nDoseTrace se ofrece únicamente con fines de seguimiento personal del bienestar. Debes tener 18 años o más para usar esta aplicación. Eres responsable de mantener la confidencialidad de las credenciales de tu cuenta.\n\nAVISO MÉDICO\nDoseTrace no proporciona asesoramiento médico. Consulta nuestro Aviso médico para más detalles.\n\nSUSCRIPCIÓN PREMIUM\nLas funciones premium están disponibles mediante suscripción al precio que se muestra en la aplicación en el momento de la compra. Las suscripciones se renuevan automáticamente salvo que se cancelen al menos 24 horas antes de la fecha de renovación. Gestiona las suscripciones en la configuración de tu ID de Apple.\n\nPROPIEDAD INTELECTUAL\nTodo el contenido, las funciones y la funcionalidad de DoseTrace son propiedad de Outcom y están protegidos por las leyes de propiedad intelectual aplicables.\n\nLIMITACIÓN DE RESPONSABILIDAD\nOutcom no será responsable de ningún daño indirecto, incidental o consecuente que surja del uso de DoseTrace.\n\nRESCISIÓN\nNos reservamos el derecho de cancelar las cuentas que infrinjan estos términos.\n\nLEY APLICABLE\nEstos términos se rigen por las leyes del estado de Florida, Estados Unidos.\n\nCONTACTO\nhello@dosetrace.io",
    settings_disclaimer: 'Aviso médico',
    settings_disclaimer_body: "AVISO DE BIENESTAR\n\nDoseTrace es una herramienta personal de seguimiento del bienestar diseñada únicamente con fines informativos y organizativos.\n\nDoseTrace no proporciona asesoramiento médico, diagnósticos ni recomendaciones de tratamiento. Todo el contenido de esta aplicación tiene únicamente fines informativos generales.\n\nNada de lo contenido en esta aplicación debe interpretarse como asesoramiento médico ni utilizarse como sustituto del asesoramiento, diagnóstico o tratamiento médico profesional. Consulta siempre a un profesional sanitario cualificado antes de iniciar, ajustar o suspender cualquier régimen de bienestar.\n\nTodas las funciones de DoseTrace son utilidades pasivas de registro de datos. Te ayudan a registrar y visualizar tus propios datos autodeclarados. No validan, respaldan ni recomiendan ningún protocolo, dosis o resultado específico. Todos los cálculos matemáticos son estimaciones basadas en los datos proporcionados por el usuario y no constituyen predicciones biológicas.\n\nAl usar DoseTrace, reconoces que:\n\n- Usas esta aplicación bajo tu propia responsabilidad\n- Asumes toda la responsabilidad por cualquier decisión tomada a partir de la información registrada en esta aplicación\n- DoseTrace y Outcom no se hacen responsables de ningún daño derivado del uso de esta aplicación\n- Esta aplicación no está destinada a diagnosticar, tratar, curar ni prevenir ninguna enfermedad o afección médica\n\nSi estás sufriendo una emergencia médica, llama de inmediato a los servicios de emergencia.",
    settings_support: 'Soporte',
    settings_faq: 'Preguntas frecuentes',
