    settings_report_empty: 'Nenhum protocolo ativo para incluir no relatório.',
    settings_data_privacy: 'Dados e privacidade',
    settings_privacy_policy: 'Política de privacidade',
    settings_privacy_body: 'POLÍTICA DE PRIVACIDADE\n\nÚltima atualização: abril de 2026\n\nA Outcom opera o aplicativo móvel DoseTrace.\n\nDADOS QUE COLETAMOS\nAo criar uma conta, coletamos seu endereço de e-mail. Opcionalmente, você pode fornecer seu nome, sexo, mês e ano de nascimento, país, objetivos de bem-estar, nível de atividade e se você trabalha com um profissional de saúde. Os dados de protocolos, registros de doses, registros de frascos e lembretes que você cria são salvos no seu dispositivo e sincronizados, criptografados em trânsito, com nossa nuvem segura (Supabase, Estados Unidos), de modo que seus dados têm backup e ficam disponíveis em seus dispositivos.\n\nCOMO USAMOS SEUS DADOS\nUsamos seus dados para fornecer e personalizar o serviço DoseTrace. As informações opcionais do perfil (nome, sexo, faixa etária, país, objetivos, nível de atividade) podem ser usadas de forma agregada e anonimizada para melhorar nosso serviço. Além da extração com IA descrita abaixo, não compartilhamos dados individuais de usuários com terceiros. Não vendemos seus dados pessoais. Não usamos seus dados de saúde para fins publicitários.\n\nEXTRAÇÃO COM IA (OPCIONAL)\nSe você optar por escanear um exame de laboratório ou carteira de vacinação, a foto ou o PDF selecionado é transmitido à Anthropic PBC (o serviço de IA Claude) para extração de texto única, somente após você dar permissão explícita no app. Apenas o arquivo selecionado é enviado. Ele é usado somente para extrair os valores, não é utilizado para treinar modelos de IA e não é retido pela Anthropic além do monitoramento antiabuso de curto prazo. A Anthropic protege esses dados com salvaguardas equivalentes a esta política.\n\nARMAZENAMENTO DE DADOS\nSeus dados são armazenados no seu dispositivo e sincronizados, criptografados em trânsito, com os servidores seguros na nuvem da Supabase nos Estados Unidos, de modo que têm backup e ficam disponíveis em seus dispositivos.\nExames de laboratório e carteiras de vacinação que você optar por escanear são, além disso, enviados uma única vez à Anthropic para extração de texto, como descrito acima.\n\nSEUS DIREITOS\nVocê pode excluir sua conta e todos os dados associados a qualquer momento em Ajustes no app, ou entrando em contato com hello@dosetrace.io.\n\nCRIANÇAS\nO DoseTrace não se destina ao uso por pessoas menores de 18 anos.\n\nALTERAÇÕES\nPodemos atualizar esta política periodicamente. O uso contínuo do aplicativo constitui aceitação da política atualizada.\n\nCONTATO\nhello@dosetrace.io',
    settings_terms: 'Termos de uso',
    settings_terms_body: "TERMOS DE SERVIÇO\n\nÚltima atualização: abril de 2026\n\nAo baixar ou usar o DoseTrace, você concorda com estes termos.\n\nUSO DO APLICATIVO\nO DoseTrace é fornecido apenas para fins de acompanhamento pessoal de bem-estar. Você deve ter 18 anos ou mais para usar este aplicativo. Você é responsável por manter a confidencialidade das credenciais da sua conta.\n\nAVISO MÉDICO\nO DoseTrace não fornece aconselhamento médico. Consulte nosso Aviso médico para mais detalhes.\n\nASSINATURA PREMIUM\nOs recursos premium estão disponíveis por assinatura pelo preço exibido no aplicativo no momento da compra. As assinaturas são renovadas automaticamente, a menos que sejam canceladas pelo menos 24 horas antes da data de renovação. Gerencie as assinaturas nas configurações do seu ID Apple.\n\nPROPRIEDADE INTELECTUAL\nTodo o conteúdo, recursos e funcionalidades do DoseTrace pertencem à Outcom e são protegidos pelas leis de propriedade intelectual aplicáveis.\n\nLIMITAÇÃO DE RESPONSABILIDADE\nA Outcom não se responsabiliza por quaisquer danos indiretos, incidentais ou consequentes decorrentes do uso do DoseTrace.\n\nRESCISÃO\nReservamo-nos o direito de encerrar contas que violem estes termos.\n\nLEI APLICÁVEL\nEstes termos são regidos pelas leis do estado da Flórida, Estados Unidos.\n\nCONTATO\nhello@dosetrace.io",
    settings_disclaimer: 'Aviso médico',
    settings_disclaimer_body: "AVISO DE BEM-ESTAR\n\nO DoseTrace é uma ferramenta pessoal de acompanhamento de bem-estar concebida apenas para fins informativos e organizacionais.\n\nO DoseTrace não fornece aconselhamento médico, diagnóstico ou recomendações de tratamento. Todo o conteúdo deste aplicativo tem apenas fins informativos gerais.\n\nNada neste aplicativo deve ser interpretado como aconselhamento médico ou utilizado como substituto de aconselhamento, diagnóstico ou tratamento médico profissional. Procure sempre a orientação de um profissional de saúde qualificado antes de iniciar, ajustar ou interromper qualquer regime de bem-estar.\n\nTodos os recursos do DoseTrace são utilitários passivos de registro de dados. Eles ajudam você a registrar e visualizar seus próprios dados autodeclarados. Não validam, endossam nem recomendam qualquer protocolo, dose ou resultado específico. Todos os cálculos matemáticos são estimativas baseadas nos dados fornecidos pelo usuário e não são previsões biológicas.\n\nAo usar o DoseTrace, você reconhece que:\n\n- Usa este aplicativo por sua própria conta e risco\n- Assume total responsabilidade por qualquer decisão tomada com base nas informações registradas neste aplicativo\n- O DoseTrace e a Outcom não se responsabilizam por qualquer dano decorrente do uso deste aplicativo\n- Este aplicativo não se destina a diagnosticar, tratar, curar ou prevenir qualquer doença ou condição médica\n\nSe você estiver enfrentando uma emergência médica, ligue imediatamente para os serviços de emergência.",
    settings_support: 'Suporte',
