    settings_report_title: 'Rapport d\'observance',
    settings_report_sub: 'Partager un résumé de 30 jours avec votre médecin',
    settings_report_empty: 'Aucun protocole actif à inclure dans le rapport.',
    settings_data_privacy: 'Données et confidentialité',
    settings_privacy_policy: 'Politique de confidentialité',
    settings_privacy_body: "POLITIQUE DE CONFIDENTIALITÉ\n\nDernière mise à jour : avril 2026\n\nOutcom exploite l'application mobile DoseTrace.\n\nDONNÉES QUE NOUS COLLECTONS\nLorsque vous créez un compte, nous collectons votre adresse e-mail. Vous pouvez éventuellement fournir votre nom, sexe, mois et année de naissance, pays, objectifs de bien-être, niveau d'activité et si vous êtes suivi par un professionnel de santé. Les données de protocoles, journaux de doses, enregistrements de flacons et rappels que vous créez sont enregistrés sur votre appareil et synchronisés, chiffrés en transit, avec notre cloud sécurisé (Supabase, États-Unis), afin que vos données soient sauvegardées et disponibles sur vos appareils.\n\nCOMMENT NOUS UTILISONS VOS DONNÉES\nNous utilisons vos données pour fournir et personnaliser le service DoseTrace. Les informations de profil facultatives (nom, sexe, tranche d'âge, pays, objectifs, niveau d'activité) peuvent être utilisées sous forme agrégée et anonymisée pour améliorer notre service. En dehors de l'extraction par IA décrite ci-dessous, nous ne partageons pas les données individuelles des utilisateurs avec des tiers. Nous ne vendons pas vos données personnelles. Nous n'utilisons pas vos données de santé à des fins publicitaires.\n\nEXTRACTION PAR IA (FACULTATIVE)\nSi vous choisissez de numériser un rapport de laboratoire ou un carnet de vaccination, la photo ou le PDF sélectionné est transmis à Anthropic PBC (le service d'IA Claude) pour une extraction de texte ponctuelle, uniquement après votre autorisation explicite dans l'app. Seul le fichier sélectionné est envoyé. Il sert uniquement à extraire les valeurs, n'est pas utilisé pour entraîner des modèles d'IA et n'est pas conservé par Anthropic au-delà de la surveillance antiabus à court terme. Anthropic protège ces données avec des garanties équivalentes à cette politique.\n\nSTOCKAGE DES DONNÉES\nVos données sont stockées sur votre appareil et synchronisées, chiffrées en transit, avec les serveurs cloud sécurisés de Supabase aux États-Unis, afin d’être sauvegardées et disponibles sur vos appareils.\nLes rapports d’analyses et carnets de vaccination que vous choisissez de numériser sont en outre envoyés une seule fois à Anthropic pour l’extraction de texte, comme décrit ci-dessus.\n\nVOS DROITS\nVous pouvez supprimer votre compte et toutes les données associées à tout moment depuis les Paramètres de l’app, ou en écrivant à hello@dosetrace.io.\n\nENFANTS\nDoseTrace n'est pas destinée à être utilisée par des personnes de moins de 18 ans.\n\nMODIFICATIONS\nNous pouvons mettre à jour cette politique périodiquement. L'utilisation continue de l'application constitue l'acceptation de la politique mise à jour.\n\nCONTACT\nhello@dosetrace.io",
    settings_terms: "Conditions d'utilisation",
    settings_terms_body: "CONDITIONS DE SERVICE\n\nDernière mise à jour : avril 2026\n\nEn téléchargeant ou en utilisant DoseTrace, vous acceptez ces conditions.\n\nUTILISATION DE L'APPLICATION\nDoseTrace est fournie uniquement à des fins de suivi personnel du bien-être. Vous devez avoir 18 ans ou plus pour utiliser cette application. Vous êtes responsable de la confidentialité des identifiants de votre compte.\n\nAVERTISSEMENT MÉDICAL\nDoseTrace ne fournit pas de conseils médicaux. Consultez notre Avertissement médical pour plus de détails.\n\nABONNEMENT PREMIUM\nLes fonctionnalités premium sont disponibles par abonnement au prix indiqué dans l'application au moment de l'achat. Les abonnements se renouvellent automatiquement sauf annulation au moins 24 heures avant la date de renouvellement. Gérez vos abonnements dans les réglages de votre identifiant Apple.\n\nPROPRIÉTÉ INTELLECTUELLE\nTout le contenu, les fonctionnalités et les fonctions de DoseTrace appartiennent à Outcom et sont protégés par les lois applicables en matière de propriété intellectuelle.\n\nLIMITATION DE RESPONSABILITÉ\nOutcom ne saurait être tenue responsable de tout dommage indirect, accessoire ou consécutif résultant de votre utilisation de DoseTrace.\n\nRÉSILIATION\nNous nous réservons le droit de résilier les comptes qui enfreignent ces conditions.\n\nDROIT APPLICABLE\nCes conditions sont régies par les lois de l'État de Floride, États-Unis.\n\nCONTACT\nhello@dosetrace.io",
    settings_disclaimer: 'Avertissement médical',
    settings_disclaimer_body: "AVERTISSEMENT BIEN-ÊTRE\n\nDoseTrace est un outil personnel de suivi du bien-être conçu uniquement à des fins d'information et d'organisation.\n\nDoseTrace ne fournit pas de conseils médicaux, de diagnostic ni de recommandations de traitement. Tout le contenu de cette application est fourni à titre informatif général uniquement.\n\nRien dans cette application ne doit être interprété comme un conseil médical ni utilisé comme substitut à un avis, un diagnostic ou un traitement médical professionnel. Demandez toujours l'avis d'un professionnel de santé qualifié avant de commencer, d'ajuster ou d'arrêter tout régime de bien-être.\n\nToutes les fonctionnalités de DoseTrace sont des utilitaires passifs d'enregistrement de données. Elles vous aident à consigner et à visualiser vos propres données autodéclarées. Elles ne valident, n'approuvent ni ne recommandent aucun protocole, dosage ou résultat particulier. Tous les calculs mathématiques sont des estimations basées sur les données fournies par l'utilisateur et ne constituent pas des prédictions biologiques.\n\nEn utilisant DoseTrace, vous reconnaissez que :\n\n- Vous utilisez cette application à vos propres risques\n- Vous assumez l'entière responsabilité de toute décision prise sur la base des informations enregistrées dans cette application\n- DoseTrace et Outcom ne sont pas responsables des préjudices résultant de l'utilisation de cette application\n- Cette application n'est pas destinée à diagnostiquer, traiter, guérir ou prévenir une quelconque maladie ou affection médicale\n\nSi vous êtes confronté à une urgence médicale, appelez immédiatement les services d'urgence.",
    settings_support: 'Support',
