    curve_disclaimer: 'Modèle estimatif basé sur des demi-vies d’élimination publiées et votre schéma prévu. La pharmacocinétique individuelle varie considérablement. Il s’agit d’une visualisation éducative — pas d’une mesure de vos taux sanguins réels. Confirmez par une vraie prise de sang. Ceci ne constitue pas un avis médical et DoseTrace n’est pas un dispositif médical.',
