    export_exported_prefix: 'Exporté le',
    cal_expl_scale_title: 'Pourquoi la balance ment (eau et glycogène)',
    cal_expl_scale_body: "Le poids sur la balance, ce n'est pas que de la graisse. Le glycogène — le glucide que vos muscles stockent comme énergie — retient environ 3 g d'eau par gramme de glycogène, et votre corps en garde à peu près 400–500 g. Rien qu'en passant de peu de glycogène (muscles vides) à des muscles pleins, la balance peut varier de 1,5–2 kg sans que ce soit de la graisse. Ajoutez le sodium, un gros repas, le cycle menstruel, le stress et une digestion normale, et 1–3 kg de fluctuation au jour le jour est tout à fait normal. Même en vrai déficit calorique, on peut voir la balance monter pendant une semaine. Impossible de calculer ces variations : pesez-vous toujours dans les mêmes conditions (le matin, après être allé aux toilettes, avant de manger) et jugez la tendance sur des semaines, pas des jours.",
    cal_expl_deficit_title: 'Pourquoi « 500 kcal = 0,5 kg/semaine » cesse de marcher',
    cal_expl_deficit_body: "La règle « 500 kcal par jour = 0,5 kg par semaine » vient de l'idée qu'un demi-kilo de graisse contient environ 3 500 kcal. C'est un bon repère à court terme, mais elle suppose que votre métabolisme ne change jamais. En perdant du poids, un corps plus petit brûle moins de calories, donc votre maintenance baisse avec lui : la perte réelle est une courbe qui s'aplatit, pas une ligne droite. S'attendre à une ligne droite et buter sur l'inévitable plateau est l'une des principales raisons pour lesquelles on croit que quelque chose ne va pas. Refaites le calcul tous les deux ou trois kilos et baissez l'objectif à mesure que votre corps change.",
    cal_expl_measure_title: 'Pourquoi les mensurations valent mieux que la balance',
    cal_expl_measure_body: "Un mètre ruban autour de la taille coûte peu et suit la perte de graisse bien plus clairement que la balance, brouillée par l'eau, la nourriture et le glycogène. Si vous mangez bien en dessous de votre maintenance, vous pouvez perdre un peu de masse maigre en même temps que la graisse : la balance stagne et vous croyez que rien ne marche. Mais si votre tour de taille diminue alors que le poids ne bouge pas, c'est de la recomposition — un vrai progrès que la balance seule ne montrerait jamais. Mesurez au même endroit, le matin au réveil, toutes les deux ou trois semaines.",
    cal_expl_comp_title: 'Pourquoi la dépense quotidienne bouge',
    cal_expl_comp_body: "Votre dépense quotidienne n'est pas un nombre figé. Le muscle brûle plus au repos que la graisse : en prenant du muscle elle monte, et en perdant du poids — surtout de la masse maigre — elle descend. C'est normal, pas un bug. C'est aussi pourquoi une mesure d'il y a quelques mois peut aujourd'hui être trop haute ou trop basse. Mesurez à nouveau vos vrais chiffres à quelques semaines d'intervalle, pour qu'ils correspondent au corps que vous avez maintenant.",
    vax_disclaimer: 'Vous saisissez vos propres vaccins. DoseTrace les enregistre et les organise — il ne vous dit jamais quels vaccins faire ni quand. Pour toute question médicale, consultez un professionnel qualifié.',
