    settings_report_empty: 'Keine aktiven Protokolle für einen Bericht.',
    settings_data_privacy: 'Daten & Datenschutz',
    settings_privacy_policy: 'Datenschutzrichtlinie',
    settings_privacy_body: "DATENSCHUTZRICHTLINIE\n\nZuletzt aktualisiert: April 2026\n\nOutcom betreibt die mobile Anwendung DoseTrace.\n\nDATEN, DIE WIR ERFASSEN\nWenn du ein Konto erstellst, erfassen wir deine E-Mail-Adresse. Optional kannst du deinen Namen, dein Geschlecht, Geburtsmonat und -jahr, Land, Wellness-Ziele, Aktivitätsniveau und ob du von einer medizinischen Fachkraft betreut wirst, angeben. Protokolldaten, Dosisprotokolle, Fläschchen-Aufzeichnungen und von dir erstellte Erinnerungen werden auf deinem Gerät gespeichert und – verschlüsselt bei der Übertragung – mit unserer sicheren Cloud (Supabase, USA) synchronisiert, sodass deine Daten gesichert und auf deinen Geräten verfügbar sind.\n\nWIE WIR DEINE DATEN VERWENDEN\nWir verwenden deine Daten, um den DoseTrace-Dienst bereitzustellen und zu personalisieren. Profilinformationen (Name, Geschlecht, Altersgruppe, Land, Ziele, Aktivitätsniveau) können in aggregierter und anonymisierter Form verwendet werden, um unseren Dienst zu verbessern. Abgesehen von der unten beschriebenen KI-Extraktion geben wir individuelle Nutzerdaten nicht an Dritte weiter. Wir verkaufen deine personenbezogenen Daten nicht. Wir verwenden deine Gesundheitsdaten nicht für Werbezwecke.\n\nKI-EXTRAKTION (OPTIONAL)\nWenn du einen Laborbericht oder Impfpass scannst, wird das ausgewählte Foto oder PDF zur einmaligen Textextraktion an Anthropic PBC (den KI-Dienst Claude) übertragen – erst nachdem du in der App ausdrücklich zugestimmt hast. Es wird nur die ausgewählte Datei gesendet. Sie dient ausschließlich der Wertextraktion, wird nicht zum Training von KI-Modellen verwendet und von Anthropic nicht über die kurzfristige Missbrauchsüberwachung hinaus gespeichert. Anthropic schützt diese Daten mit dieser Richtlinie gleichwertigen Schutzmaßnahmen.\n\nDATENSPEICHERUNG\nDeine Daten werden auf deinem Gerät gespeichert und – verschlüsselt bei der Übertragung – mit den sicheren Supabase-Cloud-Servern in den USA synchronisiert, sodass sie gesichert und auf deinen Geräten verfügbar sind.\nLaborberichte und Impfpässe, die du scannst, werden zusätzlich einmalig an Anthropic zur Textextraktion gesendet, wie oben beschrieben.\n\nDEINE RECHTE\nDu kannst dein Konto und alle zugehörigen Daten jederzeit in den Einstellungen der App löschen oder dich an hello@dosetrace.io wenden.\n\nKINDER\nDoseTrace ist nicht für die Nutzung durch Personen unter 18 Jahren bestimmt.\n\nÄNDERUNGEN\nWir können diese Richtlinie regelmäßig aktualisieren. Die fortgesetzte Nutzung der App stellt die Annahme der aktualisierten Richtlinie dar.\n\nKONTAKT\nhello@dosetrace.io",
    settings_terms: 'Nutzungsbedingungen',
    settings_terms_body: "NUTZUNGSBEDINGUNGEN\n\nZuletzt aktualisiert: April 2026\n\nDurch das Herunterladen oder Verwenden von DoseTrace stimmst du diesen Bedingungen zu.\n\nNUTZUNG DER APP\nDoseTrace wird ausschließlich zu Zwecken des persönlichen Wellness-Trackings bereitgestellt. Du musst mindestens 18 Jahre alt sein, um diese App zu nutzen. Du bist für die Vertraulichkeit deiner Kontozugangsdaten verantwortlich.\n\nMEDIZINISCHER HAFTUNGSAUSSCHLUSS\nDoseTrace bietet keine medizinische Beratung. Weitere Einzelheiten findest du in unserem medizinischen Haftungsausschluss.\n\nPREMIUM-ABONNEMENT\nPremium-Funktionen sind per Abonnement zu dem in der App zum Zeitpunkt des Kaufs angezeigten Preis verfügbar. Abonnements verlängern sich automatisch, sofern sie nicht mindestens 24 Stunden vor dem Verlängerungsdatum gekündigt werden. Verwalte Abonnements in den Einstellungen deiner Apple-ID.\n\nGEISTIGES EIGENTUM\nAlle Inhalte, Funktionen und Funktionalitäten von DoseTrace sind Eigentum von Outcom und durch die geltenden Gesetze zum Schutz des geistigen Eigentums geschützt.\n\nHAFTUNGSBESCHRÄNKUNG\nOutcom haftet nicht für indirekte, zufällige oder Folgeschäden, die aus deiner Nutzung von DoseTrace entstehen.\n\nKÜNDIGUNG\nWir behalten uns das Recht vor, Konten zu kündigen, die gegen diese Bedingungen verstoßen.\n\nGELTENDES RECHT\nDiese Bedingungen unterliegen den Gesetzen des Bundesstaates Florida, Vereinigte Staaten.\n\nKONTAKT\nhello@dosetrace.io",
    settings_disclaimer: 'Medizinischer Haftungsausschluss',
    settings_disclaimer_body: "WELLNESS-HAFTUNGSAUSSCHLUSS\n\nDoseTrace ist ein persönliches Wellness-Tracking-Tool, das ausschließlich zu Informations- und Organisationszwecken dient.\n\nDoseTrace bietet keine medizinische Beratung, Diagnose oder Behandlungsempfehlungen. Alle Inhalte in dieser App dienen ausschließlich allgemeinen Informationszwecken.\n\nNichts in dieser App darf als medizinische Beratung ausgelegt oder als Ersatz für professionelle medizinische Beratung, Diagnose oder Behandlung verwendet werden. Hol dir stets den Rat einer qualifizierten medizinischen Fachkraft ein, bevor du ein Wellness-Programm beginnst, anpasst oder beendest.\n\nAlle Funktionen in DoseTrace sind passive Hilfsmittel zur Datenerfassung. Sie helfen dir, deine eigenen selbst angegebenen Daten zu erfassen und zu visualisieren. Sie bestätigen, empfehlen oder befürworten kein bestimmtes Protokoll, keine Dosierung und kein Ergebnis. Alle mathematischen Berechnungen sind Schätzungen auf Grundlage der vom Benutzer angegebenen Daten und stellen keine biologischen Vorhersagen dar.\n\nDurch die Nutzung von DoseTrace erkennst du an, dass:\n\n- du diese App auf eigenes Risiko nutzt\n- du die volle Verantwortung für alle Entscheidungen übernimmst, die auf den in dieser App erfassten Informationen beruhen\n- DoseTrace und Outcom nicht für Schäden haften, die aus der Nutzung dieser App entstehen\n- Diese App nicht dazu bestimmt ist, Krankheiten oder gesundheitliche Beschwerden zu diagnostizieren, zu behandeln, zu heilen oder ihnen vorzubeugen\n\nWenn du dich in einem medizinischen Notfall befindest, rufe sofort den Notdienst.",
