    cal_rc_why_title: 'Woran das wahrscheinlich liegt',
    cal_rc_why_1: 'Ein Standardrechner nutzt dein Gesamtgewicht, nicht deine fettfreie Masse – das allein kann einige hundert kcal ausmachen.',
    cal_rc_why_2: 'Das Aktivitätsniveau wird am häufigsten zu hoch gewählt. Wähle im Zweifel eine Stufe niedriger.',
    cal_rc_why_3: 'Wenn du abnimmst, verbraucht ein kleinerer Körper weniger – dein altes Ziel liegt jetzt näher am Erhalt.',
    cal_rc_why_4: 'Man isst meist mehr, als man denkt. Das ist insgesamt der häufigste Grund.',
    cal_rc_why_5: 'Wasser und Glykogen können echten Fettabbau wochenlang verdecken – siehe die Erklärungen unten.',
    cal_rc_unreliable_note: 'Selbst angegebene Zufuhr liegt oft 20–40 % daneben, und dieser Fehler steckt in dieser Zahl. Wirkt sie unplausibel niedrig, ist das selbst ein Hinweis, dass du mehr isst, als du denkst.',
    cal_rc_too_short: 'Dieser Zeitraum ist zu kurz. Für eine aussagekräftige Zahl brauchst du zwei Wägungen mit mindestens 14 Tagen Abstand.',
    cal_rc_maintenance: 'Dein Gewicht hat sich kaum verändert – das entspricht im Grunde deinem Erhaltungsbedarf; die Änderung ist zu klein, um einen verlässlichen Verbrauch zu berechnen.',
    cal_rc_implausible: 'Das Ergebnis ist unplausibel niedrig, was fast immer heißt, dass die tägliche Zufuhr höher war, als man denkt (eine Unterschätzung um 20–40 % ist gut belegt). Vertraue der Schätzung oben und trag dein Essen genauer ein.',
