    export_exported_prefix: 'Exportiert am',
    cal_expl_scale_title: 'Warum die Waage lügt (Wasser & Glykogen)',
    cal_expl_scale_body: 'Das Gewicht auf der Waage ist nicht nur Fett. Glykogen – das Kohlenhydrat, das deine Muskeln als Energie speichern – bindet etwa 3 g Wasser pro Gramm Glykogen, und dein Körper hält davon rund 400–500 g. Allein der Wechsel von wenig Glykogen (leere Muskeln) zu vollen Muskeln kann die Waage um 1,5–2 kg schwanken lassen, ohne dass sich am Fett etwas ändert. Dazu Natrium, eine große Mahlzeit, der Menstruationszyklus, Stress und normale Verdauung – und 1–3 kg tägliche Schwankung sind völlig normal. Selbst in einem echten Kaloriendefizit kann die Waage eine Woche lang steigen. Diese Schwankungen lassen sich nicht wegrechnen: Wieg dich immer unter denselben Bedingungen (morgens, nach dem Toilettengang, vor dem Essen) und beurteile den Trend über Wochen, nicht über Tage.',
    cal_expl_deficit_title: 'Warum „500 kcal = 0,5 kg/Woche“ nicht mehr aufgeht',
    cal_expl_deficit_body: 'Die Regel „500 kcal pro Tag = 0,5 kg pro Woche“ beruht darauf, dass ein halbes Kilo Fett etwa 3.500 kcal enthält. Als kurzfristiger Richtwert ist das in Ordnung, aber es setzt voraus, dass sich dein Stoffwechsel nie ändert. Wenn du abnimmst, verbraucht ein kleinerer Körper weniger Kalorien, also sinkt dein Erhaltungsbedarf mit – echter Abbau ist eine Kurve, die abflacht, keine Gerade. Eine Gerade zu erwarten und auf das unvermeidliche Plateau zu treffen, ist einer der größten Gründe, warum Leute denken, etwas sei kaputt. Rechne alle paar Kilo neu und senke das Ziel, während sich dein Körper verändert.',
    cal_expl_measure_title: 'Warum Maße besser sind als die Waage',
    cal_expl_measure_body: 'Ein Maßband um die Taille kostet wenig und zeigt Fettabbau viel klarer als die Waage, die von Wasser, Essen und Glykogen getrübt wird. Wenn du deutlich unter deinem Erhaltungsbedarf isst, verlierst du vielleicht etwas fettfreie Masse zusammen mit Fett – die Waage stagniert und du denkst, es klappt nicht. Aber wenn deine Taille schrumpft, während das Gewicht gleich bleibt, ist das Rekomposition – echter Fortschritt, den die Waage allein nie zeigen würde. Miss an derselben Stelle, morgens direkt nach dem Aufstehen, alle paar Wochen.',
    cal_expl_comp_title: 'Warum sich der Tagesverbrauch ändert',
    cal_expl_comp_body: 'Dein Tagesverbrauch ist keine feste Zahl. Muskeln verbrauchen in Ruhe mehr als Fett, also steigt sie mit mehr Muskeln – und beim Abnehmen, vor allem bei Verlust von Magermasse, sinkt sie. Das ist normal, kein Fehler. Deshalb kann eine Messung von vor ein paar Monaten heute zu hoch oder zu niedrig sein. Miss deine echten Zahlen alle paar Wochen neu, damit sie zu dem Körper passen, den du jetzt hast.',
    vax_disclaimer: 'Du erfasst deine eigenen Impfeinträge. DoseTrace speichert und ordnet sie – es rät nie, welche Impfungen wann nötig sind. Bei medizinischen Fragen wende dich an eine qualifizierte Fachkraft.',
