    vax_scan_error_sub: 'Beim Lesen ist etwas schiefgelaufen. Versuche es erneut oder füge es von Hand hinzu.',
    vax_scan_none: 'Es konnten keine Impfungen gelesen werden. Versuche ein schärferes Foto oder füge sie von Hand hinzu.',
    vial_scan_cta: 'Fläschchen-Etikett scannen',
    vial_scan_scanning: 'Etikett wird gelesen…',
    vial_scan_review: 'Wir haben diese Felder aus dem Etikett deines Fläschchens ausgefüllt. Prüfe jeden Wert vor dem Speichern – die App hat das Etikett gelesen, nicht überprüft.',
    vial_scan_choose_title: 'Fläschchen-Etikett scannen',
    vial_scan_choose_sub: 'Mach ein Foto vom Etikett des Fläschchens oder wähle eines aus deiner Galerie. Wir lesen Substanz und Stärke aus, um die Felder auszufüllen.',
    vial_scan_error: 'Etikett konnte nicht gelesen werden',
