    settings_silent_sub: 'Sospendi tutte le notifiche',
    settings_persistent: 'Promemoria persistenti',
    settings_persistent_sub: 'Ripete i promemoria ogni 5 min finché non confermi',
    settings_report_title: 'Report di aderenza',
    settings_report_sub: 'Condividi un riepilogo di 30 giorni con il tuo medico',
    settings_report_empty: 'Nessun protocollo attivo da includere nel report.',
    settings_data_privacy: 'Dati e privacy',
    settings_privacy_policy: 'Informativa sulla privacy',
    settings_privacy_body: "INFORMATIVA SULLA PRIVACY\n\nUltimo aggiornamento: aprile 2026\n\nOutcom gestisce l'applicazione mobile DoseTrace.\n\nDATI CHE RACCOGLIAMO\nQuando crei un account, raccogliamo il tuo indirizzo e-mail. Facoltativamente puoi fornire nome, sesso, mese e anno di nascita, paese, obiettivi di benessere, livello di attività e se sei seguito da un professionista sanitario. I dati dei protocolli, i registri delle dosi, i registri dei flaconi e i promemoria che crei vengono salvati sul tuo dispositivo e sincronizzati, cifrati in transito, con il nostro cloud sicuro (Supabase, Stati Uniti), così i tuoi dati hanno un backup e sono disponibili sui tuoi dispositivi.\n\nCOME USIAMO I TUOI DATI\nUsiamo i tuoi dati per fornire e personalizzare il servizio DoseTrace. Le informazioni facoltative del profilo (nome, sesso, fascia d'età, paese, obiettivi, livello di attività) possono essere utilizzate in forma aggregata e anonimizzata per migliorare il nostro servizio. A parte l'estrazione con IA descritta sotto, non condividiamo i dati dei singoli utenti con terze parti. Non vendiamo i tuoi dati personali. Non utilizziamo i tuoi dati sanitari per scopi pubblicitari.\n\nESTRAZIONE CON IA (FACOLTATIVA)\nSe scegli di scansionare un referto di laboratorio o un libretto vaccinale, la foto o il PDF selezionato viene trasmesso ad Anthropic PBC (il servizio di IA Claude) per un'estrazione di testo una tantum, solo dopo il tuo permesso esplicito nell'app. Viene inviato solo il file selezionato. Serve esclusivamente a estrarre i valori, non viene utilizzato per addestrare modelli di IA e non viene conservato da Anthropic oltre il monitoraggio antiabusi a breve termine. Anthropic protegge questi dati con tutele equivalenti a questa informativa.\n\nARCHIVIAZIONE DEI DATI\nI tuoi dati sono archiviati sul tuo dispositivo e sincronizzati, cifrati in transito, con i server cloud sicuri di Supabase negli Stati Uniti, così hanno un backup e sono disponibili sui tuoi dispositivi.\nI referti di laboratorio e i libretti vaccinali che scegli di scansionare vengono inoltre inviati una sola volta ad Anthropic per l’estrazione del testo, come descritto sopra.\n\nI TUOI DIRITTI\nPuoi eliminare il tuo account e tutti i dati associati in qualsiasi momento dalle Impostazioni nell'app, o contattando hello@dosetrace.io.\n\nMINORI\nDoseTrace non è destinata all'uso da parte di persone di età inferiore ai 18 anni.\n\nMODIFICHE\nPossiamo aggiornare periodicamente questa informativa. L'uso continuato dell'app costituisce accettazione dell'informativa aggiornata.\n\nCONTATTO\nhello@dosetrace.io",
    settings_terms: 'Termini di servizio',
    settings_terms_body: "TERMINI DI SERVIZIO\n\nUltimo aggiornamento: aprile 2026\n\nScaricando o utilizzando DoseTrace, accetti questi termini.\n\nUSO DELL'APP\nDoseTrace è fornita esclusivamente per scopi di monitoraggio personale del benessere. Devi avere almeno 18 anni per utilizzare questa app. Sei responsabile della riservatezza delle credenziali del tuo account.\n\nAVVERTENZA MEDICA\nDoseTrace non fornisce consulenza medica. Consulta la nostra Avvertenza medica per maggiori dettagli.\n\nABBONAMENTO PREMIUM\nLe funzioni premium sono disponibili tramite abbonamento al prezzo indicato nell'app al momento dell'acquisto. Gli abbonamenti si rinnovano automaticamente se non vengono annullati almeno 24 ore prima della data di rinnovo. Gestisci gli abbonamenti nelle impostazioni del tuo ID Apple.\n\nPROPRIETÀ INTELLETTUALE\nTutti i contenuti, le caratteristiche e le funzionalità di DoseTrace sono di proprietà di Outcom e protetti dalle leggi vigenti in materia di proprietà intellettuale.\n\nLIMITAZIONE DI RESPONSABILITÀ\nOutcom non sarà responsabile per eventuali danni indiretti, incidentali o consequenziali derivanti dall'uso di DoseTrace.\n\nRISOLUZIONE\nCi riserviamo il diritto di chiudere gli account che violano questi termini.\n\nLEGGE APPLICABILE\nQuesti termini sono regolati dalle leggi dello Stato della Florida, Stati Uniti.\n\nCONTATTO\nhello@dosetrace.io",
    settings_disclaimer: 'Avvertenza medica',
    settings_disclaimer_body: "AVVERTENZA SUL BENESSERE\n\nDoseTrace è uno strumento personale di monitoraggio del benessere progettato esclusivamente per scopi informativi e organizzativi.\n\nDoseTrace non fornisce consulenza medica, diagnosi o raccomandazioni terapeutiche. Tutti i contenuti di questa app hanno finalità puramente informative generali.\n\nNulla in questa app deve essere interpretato come consulenza medica o utilizzato in sostituzione di consulenza, diagnosi o trattamento medico professionale. Chiedi sempre il parere di un professionista sanitario qualificato prima di iniziare, modificare o interrompere qualsiasi regime di benessere.\n\nTutte le funzioni di DoseTrace sono strumenti passivi di registrazione dei dati. Ti aiutano a registrare e visualizzare i dati che dichiari tu stesso. Non convalidano, approvano né raccomandano alcun protocollo, dosaggio o risultato specifico. Tutti i calcoli matematici sono stime basate sui dati forniti dall'utente e non costituiscono previsioni biologiche.\n\nUtilizzando DoseTrace, riconosci che:\n\n- Utilizzi questa app a tuo rischio\n- Ti assumi la piena responsabilità di qualsiasi decisione presa sulla base delle informazioni registrate in questa app\n- DoseTrace e Outcom non sono responsabili per eventuali danni derivanti dall'uso di questa app\n- Questa app non è destinata a diagnosticare, trattare, curare o prevenire alcuna malattia o condizione medica\n\nIn caso di emergenza medica, chiama immediatamente i servizi di emergenza.",
    settings_support: 'Supporto',
