    cal_intro_title: 'Cos\'è',
    cal_intro_body: 'Il tuo metabolismo basale (BMR) è, in parole semplici, quante calorie il tuo corpo brucia a riposo ogni giorno, solo per tenerti in vita. Inserisci i tuoi dati una volta e il calcolatore stima quel numero, insieme alle calorie e alle proteine giornaliere adatte al tuo obiettivo. Indicare la percentuale di grasso corporeo rende la stima più precisa, perché il calcolo può partire dalla tua massa magra. Ogni pesata viene salvata, così puoi seguire come cambiano i numeri nel tempo.',
