    cal_rc_why_1: 'Un calcolatore generico ha usato il tuo peso totale, non la massa magra: già questo può spostare la stima di qualche centinaio di kcal.',
    cal_rc_why_2: 'Il livello di attività è il dato più sovrastimato. Nel dubbio, scegline uno più basso.',
